import { useEffect, useMemo, useRef, useState } from "react";
import AMapLoader from "@amap/amap-jsapi-loader";
import {
  Bar,
  BarChart,
  CartesianGrid,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import { fetchAnalysis, fetchDataRange, fetchPublicConfig, fetchTraffic } from "./api/client";
import "./App.css";

const INTERVAL_OPTIONS = [10, 20, 30];
const DIRECTION_OPTIONS = ["全部方向", "东向西", "西向东", "南向北", "北向南"];
const SEGMENT_ORDER = ["星峰路康田路交叉口", "星峰路交叉口", "星光大道北延申段", "恒福路"];

function toApiTime(value) {
  return value ? value.replace("T", " ") : undefined;
}

function toInputTime(dateOrStr) {
  const date = new Date(dateOrStr);
  if (Number.isNaN(date.getTime())) return "";
  const pad = (v) => `${v}`.padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(
    date.getHours()
  )}:${pad(date.getMinutes())}`;
}

function formatBucket(ts) {
  const d = new Date(ts);
  const h = `${d.getHours()}`.padStart(2, "0");
  const m = `${d.getMinutes()}`.padStart(2, "0");
  return `${h}:${m}`;
}

function isRangeValid(startInput, endInput) {
  const start = new Date(startInput).getTime();
  const end = new Date(endInput).getTime();
  return Number.isFinite(start) && Number.isFinite(end) && end - start >= 3600000;
}

function levelColor(value) {
  if (value >= 60) return "#e14e2d";
  if (value >= 30) return "#f0be3d";
  return "#2db87d";
}

function nameAlias(rawName) {
  const map = {
    星峰路左: "星峰路康田路交叉口",
    星峰路北: "星峰路交叉口",
    星光大道: "星光大道北延申段",
  };
  return map[rawName] || rawName;
}

function getRoadAverageMap(rows) {
  const grouped = new Map();
  rows.forEach((row) => {
    const name = nameAlias(row.site_name);
    const current = grouped.get(name) || { sum: 0, n: 0 };
    current.sum += row.vehicle_count;
    current.n += 1;
    grouped.set(name, current);
  });
  const result = new Map();
  grouped.forEach((v, k) => result.set(k, v.n ? v.sum / v.n : 0));
  return result;
}

function getMarkerOffset(index) {
  const delta = [
    [0, 0],
    [8, -6],
    [-8, 6],
    [10, 8],
    [-10, -8],
  ];
  return delta[index % delta.length];
}

function App() {
  const [amapKey, setAmapKey] = useState("");
  const [intersections, setIntersections] = useState([]);
  const [selectedRoad, setSelectedRoad] = useState("");

  const [flowRoad, setFlowRoad] = useState("全部路口平均");
  const [speedRoad, setSpeedRoad] = useState("全部路口平均");
  const [direction, setDirection] = useState("全部方向");
  const [intervalMinutes, setIntervalMinutes] = useState(10);

  const [startInput, setStartInput] = useState("");
  const [endInput, setEndInput] = useState("");
  const [timeRangeLimit, setTimeRangeLimit] = useState({ min: "", max: "" });
  const [applied, setApplied] = useState(null);

  const [flowData, setFlowData] = useState([]);
  const [speedData, setSpeedData] = useState([]);
  const [rawTrafficRows, setRawTrafficRows] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const mapContainerRef = useRef(null);
  const mapRef = useRef(null);
  const AMapRef = useRef(null);
  const polylineRef = useRef([]);

  useEffect(() => {
    let active = true;
    async function bootstrap() {
      try {
        const [cfg, range] = await Promise.all([fetchPublicConfig(), fetchDataRange()]);
        if (!active) return;

        setAmapKey(cfg.amap_api_key);
        const sites = (cfg.intersections || []).filter((x) => x.longitude || x.latitude);
        setIntersections(sites);
        if (sites.length) setSelectedRoad(sites[0].site_name);

        const minInput = toInputTime(range.min_timestamp);
        const maxInput = toInputTime(range.max_timestamp);
        const start = minInput;
        const startDate = new Date(start);
        const proposedEnd = new Date(startDate.getTime() + 3600000);
        const maxDate = new Date(maxInput);
        const end = toInputTime(proposedEnd <= maxDate ? proposedEnd : maxDate);

        setTimeRangeLimit({ min: minInput, max: maxInput });
        setStartInput(start);
        setEndInput(end);
        setApplied({
          start,
          end,
          interval: 10,
          direction: "全部方向",
        });
      } catch (err) {
        if (!active) return;
        setError(`初始化失败：${err.message}`);
      }
    }
    bootstrap();
    return () => {
      active = false;
    };
  }, []);

  useEffect(() => {
    if (!amapKey || !mapContainerRef.current || !intersections.length) return undefined;
    let destroyed = false;

    async function initMap() {
      try {
        const AMap = await AMapLoader.load({
          key: amapKey,
          version: "2.0",
          plugins: ["AMap.Scale", "AMap.ToolBar"],
        });
        if (destroyed) return;
        AMapRef.current = AMap;

        const center = [intersections[0].longitude, intersections[0].latitude];
        const map = new AMap.Map(mapContainerRef.current, {
          center,
          zoom: 15,
          viewMode: "2D",
        });
        map.addControl(new AMap.Scale());
        map.addControl(new AMap.ToolBar({ position: "LB" }));
        mapRef.current = map;

        intersections.forEach((site, index) => {
          const offset = getMarkerOffset(index);
          const marker = new AMap.Marker({
            position: [site.longitude, site.latitude],
            title: site.site_name,
            offset: new AMap.Pixel(offset[0], offset[1]),
            label: {
              direction: "top",
              content: `<div class="amap-label">${site.site_name}</div>`,
              offset: new AMap.Pixel(offset[0], offset[1] - 6),
            },
          });
          marker.on("click", () => setSelectedRoad(site.site_name));
          marker.setMap(map);
        });
      } catch (err) {
        setError(
          `地图加载失败：${err.message}。若底图空白，请检查高德 Web JS Key 的域名白名单是否包含 localhost。`
        );
      }
    }

    initMap();

    return () => {
      destroyed = true;
      if (mapRef.current) {
        mapRef.current.destroy();
        mapRef.current = null;
      }
      polylineRef.current = [];
    };
  }, [amapKey, intersections]);

  useEffect(() => {
    if (!applied) return;
    let active = true;
    async function loadData() {
      try {
        setLoading(true);
        setError("");
        const common = {
          start_time: toApiTime(applied.start),
          end_time: toApiTime(applied.end),
          interval_minutes: applied.interval,
          direction: applied.direction === "全部方向" ? undefined : applied.direction,
        };
        const [f1, f2, traffic] = await Promise.all([
          fetchAnalysis({ ...common, road_name: flowRoad === "全部路口平均" ? undefined : flowRoad }),
          fetchAnalysis({ ...common, road_name: speedRoad === "全部路口平均" ? undefined : speedRoad }),
          fetchTraffic({ ...common, limit: 4000 }),
        ]);
        if (!active) return;
        setFlowData((f1 || []).map((v) => ({ ...v, bucketLabel: formatBucket(v.bucket_start) })));
        setSpeedData((f2 || []).map((v) => ({ ...v, bucketLabel: formatBucket(v.bucket_start) })));
        setRawTrafficRows(traffic || []);
      } catch (err) {
        if (!active) return;
        setError(`数据加载失败：${err.message}`);
      } finally {
        if (active) setLoading(false);
      }
    }
    loadData();
    return () => {
      active = false;
    };
  }, [applied, flowRoad, speedRoad]);

  useEffect(() => {
    if (!mapRef.current || !selectedRoad) return;
    const site = intersections.find((x) => x.site_name === selectedRoad);
    if (site) mapRef.current.setCenter([site.longitude, site.latitude]);
  }, [selectedRoad, intersections]);

  const roadOptions = useMemo(
    () => ["全部路口平均", ...intersections.map((x) => x.site_name)],
    [intersections]
  );
  const roadAvgMap = useMemo(() => getRoadAverageMap(rawTrafficRows), [rawTrafficRows]);

  useEffect(() => {
    if (!mapRef.current || !AMapRef.current || intersections.length < 2) return;
    polylineRef.current.forEach((line) => line.setMap(null));
    polylineRef.current = [];

    const ordered = SEGMENT_ORDER.map((name) => intersections.find((x) => x.site_name === name)).filter(Boolean);
    for (let i = 0; i < ordered.length - 1; i += 1) {
      const from = ordered[i];
      const to = ordered[i + 1];
      const avg = ((roadAvgMap.get(from.site_name) || 0) + (roadAvgMap.get(to.site_name) || 0)) / 2;
      const line = new AMapRef.current.Polyline({
        path: [
          [from.longitude, from.latitude],
          [to.longitude, to.latitude],
        ],
        strokeColor: levelColor(avg),
        strokeWeight: 8,
        strokeOpacity: 0.9,
        lineCap: "round",
      });
      line.setMap(mapRef.current);
      polylineRef.current.push(line);
    }
  }, [roadAvgMap, intersections]);

  function handleApplyTime() {
    if (!isRangeValid(startInput, endInput)) {
      setError("结束时间必须至少比起始时间晚 1 小时。");
      return;
    }
    setApplied({ start: startInput, end: endInput, interval: intervalMinutes, direction });
  }

  return (
    <div className="app-shell">
      <div className="main-layout">
        <section className="left-map-panel">
          <div className="panel-title">实时流量地图</div>
          <div className="time-card">
            <label>起始时间</label>
            <input
              type="datetime-local"
              value={startInput}
              min={timeRangeLimit.min}
              max={timeRangeLimit.max}
              onChange={(e) => setStartInput(e.target.value)}
            />

            <label>结束时间</label>
            <input
              type="datetime-local"
              value={endInput}
              min={timeRangeLimit.min}
              max={timeRangeLimit.max}
              onChange={(e) => setEndInput(e.target.value)}
            />

            <div className="time-row">
              <select value={intervalMinutes} onChange={(e) => setIntervalMinutes(Number(e.target.value))}>
                {INTERVAL_OPTIONS.map((v) => (
                  <option key={v} value={v}>
                    {v} 分钟粒度
                  </option>
                ))}
              </select>
              <select value={direction} onChange={(e) => setDirection(e.target.value)}>
                {DIRECTION_OPTIONS.map((x) => (
                  <option key={x} value={x}>
                    {x}
                  </option>
                ))}
              </select>
            </div>
            <button type="button" onClick={handleApplyTime}>
              查询
            </button>
          </div>
          <div className="map-frame" ref={mapContainerRef} />
        </section>

        <aside className="right-panel">
          <section className="section-block">
            <h2>数据分析展示</h2>
            <div className="chart-card">
              <div className="chart-head">
                <h3>车流量柱状图</h3>
                <select value={flowRoad} onChange={(e) => setFlowRoad(e.target.value)}>
                  {roadOptions.map((name) => (
                    <option key={name} value={name}>
                      {name}
                    </option>
                  ))}
                </select>
              </div>
              <ResponsiveContainer width="100%" height={250}>
                <BarChart data={flowData}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="bucketLabel" />
                  <YAxis />
                  <Tooltip />
                  <Bar dataKey="vehicle_count" fill="#2f86ff" />
                </BarChart>
              </ResponsiveContainer>
            </div>

            <div className="chart-card">
              <div className="chart-head">
                <h3>车速柱状图</h3>
                <select value={speedRoad} onChange={(e) => setSpeedRoad(e.target.value)}>
                  {roadOptions.map((name) => (
                    <option key={name} value={name}>
                      {name}
                    </option>
                  ))}
                </select>
              </div>
              <ResponsiveContainer width="100%" height={250}>
                <BarChart data={speedData}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="bucketLabel" />
                  <YAxis />
                  <Tooltip />
                  <Bar dataKey="avg_speed" fill="#22b88f" />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </section>

          <section className="section-block">
            <h2>预测</h2>
            <div className="dev-card">开发中</div>
          </section>
        </aside>
      </div>

      {loading ? <div className="floating-tip">数据更新中...</div> : null}
      {error ? <div className="floating-error">{error}</div> : null}
    </div>
  );
}

export default App;
